  if(tool!=='pen')state.drawingPath=null;
  state.tool = tool; document.body.dataset.tool = tool;
  document.querySelectorAll('[data-tool-group]').forEach(el=>{if(el.dataset.toolGroup.split(',').includes(tool)){const entry=tools.find(item=>item[0]===tool);el.dataset.tool=tool;el.title=entry[2]+(entry[3]?' ('+entry[3]+')':'');el.setAttribute('aria-label',entry[2]);el.querySelector('img').src='icons/'+entry[1]+'.svg';}});
