function showDialog(title, fields, confirm = true, onInput = null) {
  // Do not replace an existing dialog while an asynchronous operation is waiting.
  if ($('#dialog').open) return Promise.resolve(null);
  $('#dialog-title').textContent = title; $('#dialog-body').replaceChildren(); $('#dialog-ok').hidden = !confirm;
  const inputs = {};
  for (const field of fields) {
    if (field.text) { const p = document.createElement('p'); p.textContent = field.text; $('#dialog-body').append(p); continue; }
    const label = document.createElement('label'); label.textContent = field.label;
    const input = document.createElement(field.options ? 'select' : field.type==='textarea'?'textarea':'input'); input.name = field.key;
    if (field.options) for (const [value, text] of field.options) { const o = document.createElement('option'); o.value = value; o.textContent = text; input.append(o); }
    else { if(field.type!=='textarea')input.type = field.type || 'text'; if(field.min != null) input.min = field.min; if(field.max != null) input.max = field.max; if(field.step != null)input.step=field.step; }
    input.value = field.value ?? ''; if(field.type === 'checkbox') input.checked = Boolean(field.value);
    inputs[field.key] = input; label.append(input); $('#dialog-body').append(label);
  }
  if(onInput)for(const input of Object.values(inputs))input.addEventListener('input',()=>onInput(Object.fromEntries(Object.entries(inputs).map(([key,field])=>[key,field.type==='checkbox'?field.checked:field.value]))));
  return new Promise(resolve => {
    $('#dialog').addEventListener('close', () => {
      resolve($('#dialog').returnValue === 'ok' ? Object.fromEntries(Object.entries(inputs).map(([key,input])=>[key,input.type === 'checkbox' ? input.checked : input.value])) : null);
    }, {once:true}); $('#dialog').showModal();
  });
}
