function attach(document) {
  state.documents.push(document); state.index = state.documents.length - 1;
  document.originalState=document.snapshot();document.addEventListener('change', render); render(); fit();
}
async function openImage(source, name, asLayer = false) {
  const image = await loadImage(source);
  if (image.width * image.height > 64000000) throw Error('This document exceeds the current 64 million pixel limit.');
  const canvas = surface(image.width, image.height); canvas.getContext('2d').drawImage(image,0,0);
  if (asLayer && doc()) { const layer = doc().addLayer(name,canvas); layer.x = Math.round((doc().width-image.width)/2); layer.y = Math.round((doc().height-image.height)/2); doc().changed(); }
  else { const document = new EditorDocument(image.width,image.height,name); document.addLayer('Background',canvas,false); document.dirty=false; attach(document); }
}
