async function importFile(file, asLayer = false) {
  if(/\.tiff?$/i.test(file.name)){const bytes=await file.arrayBuffer(),pages=tiffPages(bytes);if(!pages.length)throw Error('No TIFF image pages were found.');let page=0;if(pages.length>1){const values=await showDialog('Open TIFF',[{key:'page',label:'Page',type:'number',min:1,max:pages.length,value:1}]);if(!values)return;page=Number(values.page)-1;if(!Number.isInteger(page)||!pages[page])throw Error('Choose a valid TIFF page.');}const canvas=readTIFF(bytes,pages[page],pages);if(asLayer&&doc()){doc().addLayer(file.name,canvas);}else{const next=new EditorDocument(canvas.width,canvas.height,file.name);next.addLayer('Background',canvas,false);next.dirty=false;attach(next);}return;}
  if(file.name.toLowerCase().endsWith('.psd')){const result=await readPSD(await file.arrayBuffer(),file.name);attach(result.document);if(result.notes.length)await showDialog('PSD Import',[{text:result.notes.join('\n')}],false);return;}
  if (file.name.toLowerCase().endsWith('.gcphoto')) { attach(await EditorDocument.fromProject(await file.text())); return; }
  const url = URL.createObjectURL(file); try { await openImage(url,file.name,asLayer); } finally { URL.revokeObjectURL(url); }
}
